-- Sacred ReBorn as a Sacred Gear mod. Sacred ReBorn is the work of the Sacred ReBorn Overlookers group (a
-- non-commercial mod group); this mod only re-creates what their exe and data change, on top of Sacred Gear:
--
--   * overlay.txt (generated by tools/reborn_port.py from the ReBorn folder) serves ReBorn's data files (the SRB
--     data, the text) where the game opens the original ones: Sacred Gear applies it when it starts;
--   * abilities_edits.json (generated too) holds the values ReBorn changes in the exe's ability tables (the combat arts
--     and the spells); this file applies them through gear.data.abilities.
--
-- With -gear-auto the mod also checks itself (see the end): Sacred.exe -gear-auto -gear-load=1 -gear-mods=reborn

local function load_edits()
    local text = gear.read('abilities_edits.json')
    if not text then return nil, 'abilities_edits.json is missing' end
    local doc, err = gear.json.decode(text)
    if not doc then return nil, err end
    local edits, count, samples = {}, 0, {}
    for _, table_edits in pairs(doc.tables) do
        for id, fields in pairs(table_edits) do
            local n = tonumber(id)
            if n then
                local e = {}
                for field, pair in pairs(fields) do
                    e[field] = pair[2]
                    count = count + 1
                    if field == 'effect_base' and #samples < 3 then samples[#samples + 1] = {id = n, field = field, value = pair[2]} end
                end
                edits[n] = e
            end
        end
    end
    return edits, count, samples
end

local applied = {count = 0, ok = false}

local function apply_abilities()
    if applied.ok or not gear.config.abilities then return end
    local edits, count, samples = load_edits()
    if not edits then
        print('abilities not applied: ' .. tostring(count))
        applied.ok = true
        return
    end
    local written, problems = gear.data.abilities:apply(edits)
    if not written then
        return      -- the tables are not there yet: again next frame
    end
    applied.ok, applied.count, applied.edits, applied.samples = true, written, count, samples
    print(('ReBorn: %d ability fields written (%d in the table)'):format(written, count))
    for i, p in ipairs(problems or {}) do
        if i <= 5 then print('ReBorn: ' .. p) end
    end
end

-- B12: ReBorn turns a level into a factor in integer tiers of 12 levels (1 up to level 12, 2 up to 24, 3 up to 36, 4 above);
-- vanilla uses (34 L + 8) / (c1 L + c2). The engine asks through the level.factor hook (six places).
-- B13: constants the engine loads inside its hit handlers and difficulty code. ReBorn points those instructions at other
-- constants: the effect scale of the four hit handlers 0.2 -> 1.0; their chance scale 0.01 -> 1.0 in two of them and, in the other two, a
-- float read from code bytes (-3.4022e35: an address typo of ReBorn's, reproduced); the five difficulty factors 1.0 1.34 1.67 2.0 2.34 ->
-- 1.06 1.08 1.10 1.12 1.14; three scales of one function 0.01 -> 0.01, 0.05, 0.05.
local REBORN_CONSTANTS = {
    ['hit.effect_scale'] = {1.0, 1.0, 1.0, 1.0},
    ['hit.chance_scale'] = {-3.4022038704631622e35, -3.4022038704631622e35, 1.0, 1.0},
    ['difficulty.factor'] = {1.06, 1.08, 1.10, 1.12, 1.14},
    ['scale.559BF0'] = {0.01, 0.05, 0.05},
}
gear.on('combat.constant', function(name, vanilla, index)
    if name == 'difficulty.scale' then
        -- ReBorn's appended code divides the 0.01 of one damage scale by 1, 1, 1, 2, 4 for the difficulty levels 0 .. 4
        local d = gear.game.difficulty() or 0
        return vanilla / (d >= 4 and 4 or d == 3 and 2 or 1)
    end
    local list = REBORN_CONSTANTS[name]
    return list and list[index + 1]
end)

local level_handler = gear.on('level.factor', function(level)
    local tier = 1
    if level > 12 then tier = 2 end
    if level > 24 then tier = 3 end
    if level > 36 then tier = 4 end
    return tier
end)

-- creature.ability (B6): the abilities the creature AI (ENG 004D4E50) picks. Keyed by the site's address; ReBorn changed these
-- immediates (vanilla in the comment), the others keep the engine's id.
local AI_ABILITY = {
    [0x4D534A] = 23,    -- 25
    [0x4D5754] = 33,    -- 29
    [0x4D60ED] = 5,     -- 40
    [0x4DA600] = 34,    -- 40
    [0x4D80DD] = 0x419, -- the base the id 0x42b adds to
    [0x4D5E68] = 0x31,  -- 0x32 - (x % 3 ~= 0): ReBorn always uses 0x31
}
gear.on('creature.ability', function(_, _, _, address)
    return AI_ABILITY[address]
end)

-- effect.add (B9): ReBorn replaces the store into a creature's effect entry (ENG 0056256D). For the player's own hero, an ability other than
-- 0x35 adds to the entry of the ability in use (not the one the loop is at), leaves the clamps out and ends the loop; ability 0x35 stores
-- nothing; every creature's effect counter is set (flag 0x4000000) or grown (flag 0x20000000). The AI's own calls keep the engine's behaviour.
local function stack_mode(flags)
    if bit.band(flags, 0x4000000) ~= 0 then return 'set' end
    if bit.band(flags, 0x20000000) ~= 0 then return 'inc' end
end
local function effect_add(e)
    local hero = gear.world.hero()
    if hero and hero.id == e.creature then
        if e.ability == 0x35 then return {clamp = true} end
        return {value = e.value, effect = e.ability, clamp = false, finish = true, stack = stack_mode(e.flags)}
    end
    return {clamp = true, stack = stack_mode(e.flags)}
end
local effect_handler = gear.on('effect.add', effect_add)

-- bonus.constant (B14, FUN_00571710 = the item bonus roller): the arguments of its random rolls. Keyed by the site's index (vanilla in the
-- comment): the upper limits of three integer rolls 5 / 15 / 15 / 5 become 20 / 20 / 120 / 20, a text id 0x482 becomes 0x496, and the
-- float amplitudes 0.15 (x4) become 0.2, the fifth 1.2.
local BONUS = {
    [0] = 0x14,     -- 5
    [1] = 0x14,     -- 15
    [2] = 0x496,    -- text 0x482
    [3] = 0x78,     -- 15
    [4] = 0x14,     -- 5
    [5] = 0.2, [6] = 0.2, [7] = 0.2, [8] = 0.2,     -- 0.15
    [9] = 1.2,      -- 0.15
}
gear.on('bonus.constant', function(index)
    return BONUS[index]
end)

-- SR_QUICK_CAST (B8): with the Settings.cfg key set to 1, choosing a skill slot with its digit key uses the skill at the cursor at once (ReBorn sends
-- the UI a mouse event at the cursor after the selection).
gear.on('skillslot.select', function()
    if gear.settings.game('SR_QUICK_CAST') == '1' or gear.config.quick_cast then
        gear.game.cursor_click()
    end
end)

-- combat.branch (B13): in the four hit handlers ReBorn flips five conditional jumps. After the creation of an effect object (types 0x34B, 0x360,
-- 0x35C, 0x35E) the `je` that skips the secondary effect when the object could not be made becomes a `jmp`: the secondary effect is never added
-- (together with the pooled 0.2 -> 1.0 of the chance rolls); in the combat art handler the test for the art 0x3FC (`jne`) is inverted.
-- More flips outside the hit handlers: the creature AI's timer test (`cmp eax, 0xB7; jne` -> `je`: now the creature type 0xB7 takes the jump),
-- the ability dispatch (`cmp eax, 0x28; jge` -> `je`: only the ability 0x28) and a clamp to 255 that is never applied (`jbe` -> `jmp`).
gear.on('combat.branch', function(name, vanilla, index, eax)
    if name == 'hit.secondary' then return true end
    if name == 'hit.condition' then return not vanilla end
    if name == 'ai.timer' then return eax == 0xB7 end
    if name == 'ability.dispatch' then return eax == 0x28 end
    if name == 'color.clamp' then return true end
end)

-- skillslot.key (B8, the cave at DE 01ACC770): ReBorn routes the digit keys itself. '1'..'5' choose the slots 1..5 as the engine does (page choice,
-- COMBINE_SLOTS check, selection); '6', '7', '8', '9', '0' choose the same slots 1..5 by the selection alone, without the COMBINE_SLOTS check.
local SLOT_KEYS = {[0x31] = 0, [0x32] = 1, [0x33] = 2, [0x34] = 3, [0x35] = 4,
                   [0x36] = {0, 'select'}, [0x37] = {1, 'select'}, [0x38] = {2, 'select'}, [0x39] = {3, 'select'}, [0x30] = {4, 'select'}}
gear.on('skillslot.key', function(character)
    local k = SLOT_KEYS[character]
    if k then return k end
    return nil
end)

gear.on('load', apply_abilities)
gear.on('frame', function()
    if not applied.ok then apply_abilities() end
end)

---------------------------------------------------------------------------------------------------------------
-- The "Changes" screen: the mod's page in the mod manager (Mods screen, F11) shows the ReBorn version and a "Changes" button that opens a
-- window with what Sacred ReBorn changes, section by section (changes.json, made from the group's changelists by
-- tools/changelog_from_docx.py).
---------------------------------------------------------------------------------------------------------------
local ui = gear.ui
local changes                       -- changes.json, decoded; false if it is missing
local function load_changes()
    if changes == nil then
        local text = gear.read('changes.json')
        local ok, data = pcall(gear.json.decode, text or '')
        changes = (ok and type(data) == 'table' and type(data.sections) == 'table') and data or false
    end
    return changes
end

local TEXT = {size = 13}
local LINE_H, GAP = 17, 7
local view = {section = 1, scroll = 0, built = nil, built_width = 0, lines = {}}
local word_width, space_width = {}, nil

local function measure(word)
    local w = word_width[word]
    if not w then
        w = ui.text_size(word, TEXT) or (#word * 7)
        word_width[word] = w
    end
    return w
end

-- the text of an item as lines no wider than `width` (the layout's units); a line starting with "- " keeps its hanging indent
local function wrap(text, width, out)
    space_width = space_width or measure('n') * 0.6
    for paragraph in (text .. '\n'):gmatch('([^\n]*)\n') do
        local line, line_w = '', 0
        local indent = paragraph:sub(1, 2) == '- ' and '   ' or ''
        for word in paragraph:gmatch('%S+') do
            local w = measure(word)
            if line ~= '' and line_w + space_width + w > width then
                out[#out + 1] = line
                line, line_w = indent .. word, measure(indent) + w
            elseif line == '' then
                line, line_w = word, w
            else
                line, line_w = line .. ' ' .. word, line_w + space_width + w
            end
        end
        out[#out + 1] = line
    end
end

local function build(width)
    local data = load_changes()
    local section = data and data.sections[view.section]
    if view.built == view.section and view.built_width == width then return end
    view.built, view.built_width, view.lines = view.section, width, {}
    if not section then return end
    for _, item in ipairs(section.items) do
        local bullet = item:sub(1, 2) == '* '
        local lines = {}
        wrap(bullet and item:sub(3) or item, width - (bullet and 14 or 0), lines)
        for i, line in ipairs(lines) do
            view.lines[#view.lines + 1] = {text = line, bullet = bullet and i == 1, indent = bullet and 14 or 0}
        end
        view.lines[#view.lines + 1] = {gap = true}
    end
end

local function reborn_version()
    local data = load_changes()
    return data and data.version or '?'
end

-- drawn every frame by the `draw` handler; open with gear.ui.show_panel('changes', true)
local function draw_changes()
    local data = load_changes()
    local p = ui.panel('changes', ('Sacred ReBorn HD - Changes (ReBorn v%s)'):format(reborn_version()), 110, 70, 800, 620,
                       {resizable = true, min_width = 460, min_height = 320, layer = 'top'})
    if not p.open then return end
    local c = ui.COLORS
    if not data then
        ui.text('changes.json is missing.', p.content_x + 10, p.content_y + 10, {layer = 'top', color = c.text})
        return
    end
    local x, y, w, h = p.content_x + 8, p.content_y + 6, p.content_w - 16, p.content_h - 12
    -- the section: previous / dropdown / next
    local titles = {}
    for i, s in ipairs(data.sections) do titles[i] = s.title end
    if ui.button('prev', x, y, 28, 22, '<', {layer = 'top'}) and view.section > 1 then view.section, view.scroll = view.section - 1, 0 end
    local changed, index = ui.dropdown('section', x + 34, y, math.min(w - 68, 360), titles, view.section, {layer = 'top'})
    if changed then view.section, view.scroll = index, 0 end
    if ui.button('next', x + 40 + math.min(w - 68, 360), y, 28, 22, '>', {layer = 'top'}) and view.section < #titles then
        view.section, view.scroll = view.section + 1, 0
    end
    -- the text of the section
    local top, bottom = y + 32, y + h - 30
    local text_w = w - 6
    build(text_w)
    local visible = math.max(1, math.floor((bottom - top) / LINE_H))
    local total = #view.lines
    local max_scroll = math.max(0, total - visible)
    view.scroll = math.max(0, math.min(max_scroll, view.scroll))
    local at = top
    for i = view.scroll + 1, math.min(total, view.scroll + visible) do
        local l = view.lines[i]
        if l.text then
            if l.bullet then ui.text('\226\128\162', x + 2, at, {layer = 'top', size = TEXT.size, color = c.accent}) end
            ui.text(l.text, x + l.indent, at, {layer = 'top', size = TEXT.size, color = c.text})
        end
        at = at + (l.gap and GAP or LINE_H)
        if at > bottom then break end
    end
    -- scrolling: buttons and a slider at the bottom
    local by = y + h - 24
    if ui.button('up', x, by, 28, 22, '^', {layer = 'top', tooltip = 'Scroll up'}) then view.scroll = math.max(0, view.scroll - 3) end
    if ui.button('down', x + 32, by, 28, 22, 'v', {layer = 'top', tooltip = 'Scroll down'}) then view.scroll = math.min(max_scroll, view.scroll + 3) end
    if max_scroll > 0 then
        local moved, value = ui.slider('scroll', x + 70, by + 3, w - 80, 0, max_scroll, view.scroll, {layer = 'top', step = 1, format = false})
        if moved then view.scroll = math.floor(value) end
    end
end

gear.on('draw', draw_changes)

-- the mod's own page in its Mods screen
gear.mods.page(function(x, y, w)
    local c = ui.COLORS
    ui.label('version', ('Sacred ReBorn HD, ReBorn version %s'):format(reborn_version()), x + 8, y + 8, {layer = 'top'})
    ui.label('note', 'The balance, bosses, enemies, heroes, items and fixes of the ReBorn mod, re-created on the plain game.', x + 8, y + 30, {layer = 'top'})
    if ui.button('changes', x + 8, y + 58, 140, 26, 'Changes', {layer = 'top', tooltip = 'What Sacred ReBorn changes, section by section'}) then
        ui.show_panel('changes', true)
    end
    return 96
end)

---------------------------------------------------------------------------------------------------------------
-- Self test (-gear-auto): the mod loaded, the overlay serves ReBorn's data, ability values read back as ReBorn's.
---------------------------------------------------------------------------------------------------------------
if not gear.auto then return end
local A = gear.auto
local results = {checks = {}, passed = 0, failed = 0}

local function check(name, ok, detail)
    results.checks[#results.checks + 1] = {name = name, ok = ok and true or false, detail = detail}
    if ok then results.passed = results.passed + 1 else results.failed = results.failed + 1 end
    print(('%s %s%s'):format(ok and 'PASS' or 'FAIL', name, detail and (': ' .. tostring(detail)) or ''))
end

gear.task(function()
    check('main menu', A.wait_for_menu(gear.config.timeout_menu))
    local game = A.wait_for_game(gear.config.timeout_game)
    check('game with a hero', game)
    gear.wait(3)
    if gear.config.idle > 0 then gear.wait(gear.config.idle) end

    do
        local h = gear.world.hero()
        if h then print(('hero: %s level %s hp %s'):format(tostring(h:class()), tostring(h:level()), tostring(h:max_hp()))) end
    end

    -- the ability values
    check('abilities applied', applied.ok and applied.count > 0, applied.count)
    local abilities = gear.data.abilities
    local wrong = 0
    for _, s in ipairs(applied.samples or {}) do
        local a = abilities[s.id]
        local v = a and a[s.field]
        local good = v and math.abs(v - s.value) < 1e-4
        check(('ability %d %s reads back as ReBorn'):format(s.id, s.field), good, v)
        if not good then wrong = wrong + 1 end
    end
    local a1000 = abilities[1000]
    if a1000 then
        check('ability names through gear.text', gear.text.get(a1000.name_text) ~= nil, gear.text.get(a1000.name_text))
    end

    -- the overlay: the rule exists, resolves into this mod, and the game opened ReBorn's balance.bin through it
    -- build every patched file now (resolving a path makes Gear patch it), so a test can compare them all with ReBorn's own files
    do
        local built = 0
        for line in (gear.read('overlay.txt') or ''):gmatch('([^' .. string.char(13, 10) .. ']+)') do
            local game = line:match('^%s*([^#=]-)%s*=%s*patch:')
            if game then gear.files.resolve(game); built = built + 1 end
        end
        print(('patched files requested: %d'):format(built))
    end
    local info = gear.files.overlay()
    check('overlay rules', info and info.files > 0, info and info.files)
    local path = gear.files.resolve('bin/balance.bin')
    check('balance.bin resolves into the mod', path:lower():gsub('\\', '/'):find('mods/reborn/cache/bin/balance.bin', 1, true) ~= nil, path)
    local served = gear.files.served('bin/balance.bin')
    check('the game read balance.bin from the mod', served > 0, served)

    -- the text overlay: ids whose text ReBorn's SRglbl.res adds or changes (text_checks.json, made by tools/text_checks.py
    -- from two runs of tools/textdump; the text depends on the language, so only for the language it was made in)
    local tc = gear.read('text_checks.json')
    tc = tc and gear.json.decode(tc)
    if tc and tc.language == gear.settings.game('LANGUAGE') then
        for _, c in ipairs(tc.checks) do
            check(('text %d is from ReBorn'):format(c.id), gear.text.get(c.id) == c.text, gear.text.get(c.id))
        end
    else
        print('text checks skipped: no text_checks.json for the game language')
    end

    -- the save folder redirect (overlay.txt: saves = save): the game read the savegame it loaded from the mod's folder
    local mine = info and info.saves
    check('saves are redirected to the mod', mine ~= nil, mine)
    local save = 0
    for slot = 0, 5 do save = save + gear.files.served(('save/game%02d.pak'):format(slot)) end
    check('the game read its savegame from the mod folder', save > 0, save)
    check('a save path resolves into the mod', gear.files.resolve('save/new.pak'):lower():gsub('\\', '/'):find('mods/reborn/save/new.pak', 1, true) ~= nil,
          gear.files.resolve('save/new.pak'))

    -- pictures for a person to look at (the models and items come from the overlay's PAKs when it serves them)
    A.screenshot('reborn-world')
    A.press('i')
    gear.wait(2)
    A.screenshot('reborn-inventory')
    A.press('i')
    gear.wait(1)

    -- the level.factor hook: call the engine's own level function (from a worker thread, so the hook can answer): ReBorn's tiers
    for _, case in ipairs({{5, 1}, {12, 1}, {13, 2}, {24, 2}, {30, 3}, {37, 4}, {80, 4}}) do
        local got
        for attempt = 1, 20 do
            if A.engine_level_factor_start(case[1]) then
                gear.wait_until(function() got = A.engine_level_factor_result(); return got ~= nil end, 3)
                if got ~= nil then break end
            end
            gear.wait(0.1)
        end
        check(('engine level function: level %d gives the tier %d'):format(case[1], case[2]), got == case[2], got)
    end

    -- without the handler the displaced vanilla block runs unchanged: trunc((34 L + 8) / (7 L + 36))
    gear.off(level_handler)
    for _, case in ipairs({{5, 2}, {20, 3}, {100, 4}}) do
        local got
        for attempt = 1, 20 do
            if A.engine_level_factor_start(case[1]) then
                gear.wait_until(function() got = A.engine_level_factor_result(); return got ~= nil end, 3)
                if got ~= nil then break end
            end
            gear.wait(0.1)
        end
        check(('engine level function without a handler: level %d gives the vanilla %d'):format(case[1], case[2]), got == case[2], got)
    end

    gear.off(effect_handler)     -- the stub tests below need to see the engine's behaviour without it
    -- the stubs of the constant site hooks, on two functions built in memory: answered through a handler of this mod, then vanilla
    local selftest_handler = gear.on('combat.constant', function(name, vanilla)
        if name == 'selftest.fmul' then return vanilla * 10 end
        if name == 'selftest.fld' then return 7.5 end
    end)
    local st
    for attempt = 1, 20 do
        if A.site_hook_selftest_start() then
            gear.wait_until(function() st = A.site_hook_selftest_result(); return st ~= nil end, 3)
            if st ~= nil then break end
        end
        gear.wait(0.1)
    end
    check('constant site stub: fmul answered by a mod (0.2 * 10)', st and math.abs(st.fmul - 2.0) < 1e-4, st and st.fmul)
    check('constant site stub: fld answered by a mod (7.5)', st and math.abs(st.fld - 7.5) < 1e-4, st and st.fld)
    check('constant site stub: eax, ecx and edx survive', st and st.registers_kept, st and tostring(st.registers_kept))
    gear.off(selftest_handler)
    st = nil
    for attempt = 1, 20 do
        if A.site_hook_selftest_start() then
            gear.wait_until(function() st = A.site_hook_selftest_result(); return st ~= nil end, 3)
            if st ~= nil then break end
        end
        gear.wait(0.1)
    end
    check('constant site stub without an answer: the vanilla constants', st and math.abs(st.fmul - 0.2) < 1e-4 and math.abs(st.fld - 0.2) < 1e-4,
          st and (st.fmul .. ' ' .. st.fld))
    check('creature.ability stubs without an answer: vanilla store 100, add 1000, block 49 (0x31)',
          st and st.ability_store == 100 and st.ability_add == 1000 and st.ability_edx == 49, st and (st.ability_store .. ' ' .. st.ability_add .. ' ' .. st.ability_edx))
    check('creature.ability stubs: registers survive', st and st.ability_kept, st and tostring(st.ability_kept))
    check('damage stub without an answer: 12.4 rounds to 12', st and st.damage == 12, st and tostring(st.damage))
    check('combat.branch rel8 stub without an answer: taken, eax untouched by the displaced add (path 2, 0x28 stays 0)', st and st.branch2_path == 2 and st.branch2_eax == 0,
          st and (st.branch2_path .. ' ' .. st.branch2_eax))
    check('combat.branch stub without an answer: the engine je is taken (2)', st and st.branch_taken == 2, st and tostring(st.branch_taken))
    check('skillslot.select stub: the displaced instruction still runs', st and st.slot_byte == 1, st and tostring(st.slot_byte))
    check('bonus.constant stubs without an answer: push 5 and push 3.5', st and st.bonus_int == 5 and math.abs(st.bonus_float - 3.5) < 1e-6,
          st and (st.bonus_int .. ' ' .. st.bonus_float))
    check('effect.add stub without an answer: the engine path (exit 1), entry 0 = 3.5, counter 4',
          st and st.effect_exit == 1 and st.effect_entry0 == 350 and st.effect_entry1 == 100 and st.effect_counter == 4,
          st and (st.effect_exit .. ' ' .. st.effect_entry0 .. ' ' .. st.effect_entry1 .. ' ' .. st.effect_counter))

    -- the same stubs answered by a handler (a fake creature of type 77)
    local effect_test = gear.on('effect.add', function(e)
        if e.creature == 5 and e.ability == 7 and e.effect == 10 then return {value = 9, effect = 11, finish = true, stack = 'inc'} end
    end)
    local branch_test = gear.on('combat.branch', function(name, vanilla, index, eax)
        if name == 'selftest.branch2' then return eax ~= 0x28 end      -- eax must arrive as 0x28: the jump is refused
    end)
    local bonus_test = gear.on('bonus.constant', function(index, vanilla)
        if index == 10 then return vanilla * 2 end      -- the self test's push imm8 site
        if index == 11 then return vanilla + 1.25 end   -- its float site
    end)
    local damage_test = gear.on('damage', function(hit)
        if hit.attacker_type == 77 then return hit.damage + 70000 end   -- over 16 bit: must saturate, not wrap
    end)
    local ability_test = gear.on('creature.ability', function(type_id, vanilla, index)
        if type_id ~= 77 then return nil end
        if vanilla == 100 then return 101 end
        if vanilla == 1000 then return 2000 end
        if vanilla == -1 then return 7 end
    end)
    st = nil
    for attempt = 1, 20 do
        if A.site_hook_selftest_start() then
            gear.wait_until(function() st = A.site_hook_selftest_result(); return st ~= nil end, 3)
            -- the worker thread cannot run Lua while the engine thread does (the stub then keeps the engine's value): try again
            if st ~= nil and st.ability_store == 101 and st.damage == 65534 and st.effect_exit == 3 and st.bonus_int == 10 and st.branch2_path == 1 then break end
        end
        gear.wait(0.1)
    end
    check('creature.ability stubs answered by a mod: store 101, add 2000, block 7',
          st and st.ability_store == 101 and st.ability_add == 2000 and st.ability_edx == 7, st and (st.ability_store .. ' ' .. st.ability_add .. ' ' .. st.ability_edx))
    check('creature.ability stubs answered: registers survive', st and st.ability_kept, st and tostring(st.ability_kept))
    check('damage stub answered above 16 bit saturates at 65534 (no wrap around)', st and st.damage == 65534, st and tostring(st.damage))
    check('effect.add stub answered by a mod: leave (exit 3), entry 1 = 9, entry 0 untouched, counter 5',
          st and st.effect_exit == 3 and st.effect_entry1 == 900 and st.effect_entry0 == 100 and st.effect_counter == 5,
          st and (st.effect_exit .. ' ' .. st.effect_entry0 .. ' ' .. st.effect_entry1 .. ' ' .. st.effect_counter))
    check('bonus.constant stubs answered by a mod: 5 -> 10, 3.5 -> 4.75', st and st.bonus_int == 10 and math.abs(st.bonus_float - 4.75) < 1e-6,
          st and (st.bonus_int .. ' ' .. st.bonus_float))
    check('combat.branch rel8 stub answered by a mod: falls through (path 1), the displaced add ran (eax 0x26)', st and st.branch2_path == 1 and st.branch2_eax == 0x26,
          st and (st.branch2_path .. ' ' .. st.branch2_eax))
    gear.off(branch_test)
    gear.off(bonus_test)
    gear.off(ability_test)
    gear.off(damage_test)
    gear.off(effect_test)
    effect_handler = gear.on('effect.add', effect_add)

    -- the Changes screen: open it and take pictures of the first section and a later one
    if gear.config.changes_shot then
        gear.ui.show_panel('changes', true)
        gear.wait(1.5)
        A.screenshot('reborn-changes-1')
        local data = load_changes()
        view.section, view.scroll = data and #data.sections or 1, 0
        gear.wait(1)
        A.screenshot('reborn-changes-2')
        view.section, view.scroll = 8, 12
        gear.wait(1)
        A.screenshot('reborn-changes-3')
        print(('changes screen: %d sections, version %s, %d lines in the last built section'):format(data and #data.sections or 0, reborn_version(), #view.lines))
        gear.ui.show_panel('changes', false)
    end

    -- pointed test of the skill slot keys: which way of typing a digit reaches the slot hook (informational)
    if gear.config.slotkeys then
        gear.config.quick_cast = true
        A.move(900, 400)
        gear.wait(1)
        local function calls() return gear.hooks.stats('skillslot.select').calls end
        -- keys 6 and 1: the routing (select half vs the whole case with the COMBINE_SLOTS check)
        for _, k in ipairs({'6', '1'}) do
            local before = calls()
            A.type(k)
            gear.wait(0.6)
            print(('routing key %s: %d new slot hook calls'):format(k, calls() - before))
        end
        local hero = gear.world.hero()
        local function where() local x, y = hero:position(); return ('%.0f,%.0f'):format(x or 0, y or 0) end
        print('hero before the slot keys at ' .. where())
        for _, down in ipairs({false, true}) do
            print(('cursor_click(down=%s): %s'):format(tostring(down), tostring(gear.game.cursor_click(down))))
            gear.wait(2)
            print(('hero after the click at %s'):format(where()))
        end
        -- enemies under the cursor, then every slot key: do the hit sites run (the hero cast something)?
        do
            local x, y, layer = hero:position()
            for i = 1, 3 do gear.world.spawn(32, x + 90 * i, y + 60, {layer = layer}) end
            gear.wait(2)
            local function snapshot()
                local t = {}
                for _, site in ipairs(gear.hooks.sites()) do
                    if site.hook ~= 'skillslot.select' then t[site.hook .. '[' .. site.index .. ']'] = site.calls end
                end
                return t
            end
            local function diff(a, b)
                local out = {}
                for k, v in pairs(b) do if v ~= (a[k] or 0) then out[#out + 1] = ('%s +%d'):format(k, v - (a[k] or 0)) end end
                return table.concat(out, ', ')
            end
            for _, quick in ipairs({false, true}) do        -- the first pass is the control: the keys without the click
                gear.config.quick_cast = quick
                for key = 1, 5 do
                    local h0, p0 = snapshot(), where()
                    A.type(tostring(key))
                    gear.wait(1.5)
                    print(('slot key %d, quick cast %s: [%s] hero %s -> %s, hp %s'):format(key, tostring(quick), diff(h0, snapshot()), p0, where(), tostring(hero:hp())))
                end
            end
        end
        for _, way in ipairs({'type', 'press', 'key_down_up'}) do
            for key = 1, 5 do
                local before = calls()
                local k = tostring(key)
                if way == 'type' then A.type(k) elseif way == 'press' then A.press(k)
                else A.key_down(k); gear.wait(0.1); A.key_up(k) end
                gear.wait(0.6)
                print(('slot key %s via %s: %d new slot hook calls'):format(k, way, calls() - before))
            end
        end
        gear.config.quick_cast = false
    end

    -- real play: does the hero's own code reach the engine's hook sites? (informational; counters per site are logged)
    if gear.config.fight > 0 then
        local function sitecalls()
            local calls = 0
            for _, site in ipairs(gear.hooks.sites()) do calls = calls + site.calls end
            return calls
        end
        local function step(name, fn)
            local before = sitecalls()
            fn()
            gear.wait(1.0)
            print(('step %s: %d new site calls'):format(name, sitecalls() - before))
        end
        -- UI paths: the combat arts tab and the skills list (tooltips)
        step('open inventory', function() A.press('i') end)
        step('combat arts tab', function() A.click(275, 423) end)
        for k, pos in ipairs({{120, 480}, {200, 480}, {280, 480}, {360, 480}, {440, 480}}) do
            step('hover art slot ' .. k, function() A.move(pos[1], pos[2]) end)
        end
        A.screenshot('reborn-arts')
        step('close inventory', function() A.press('i') end)
        step('character window', function() A.press('c') end)
        for k, pos in ipairs({{1180, 90}, {1180, 112}, {1180, 135}}) do
            step('hover skill ' .. k, function() A.move(pos[1], pos[2]) end)
        end
        step('close character', function() A.press('c') end)

        -- the belt's orbs: tooltips of the weapon slots and of the right hand arts
        for k, pos in ipairs({{987, 843}, {1063, 843}, {1143, 843}, {470, 843}, {560, 843}, {640, 843}}) do
            step('hover belt orb ' .. k, function() A.move(pos[1], pos[2]) end)
        end
        A.screenshot('reborn-belt-tooltip')
        A.move(800, 300)

        local hero = gear.world.hero()
        if hero then
            local x, y, layer = hero:position()
            for i = 1, 3 do gear.world.spawn(32, x + 90 * i, y + 60, {layer = layer}) end
            gear.wait(3)
            -- the belt's right hand art (the green sword) is used with the right mouse button: right clicks around the hero
            for round = 1, 3 do
                for k = 0, 7 do
                    local th = k * math.pi / 4
                    step(('right click %d.%d (combat art)'):format(round, k), function()
                        A.click(803 + 80 * math.cos(th), 465 + 48 * math.sin(th), 'rbutton')
                    end)
                end
            end
            A.screenshot('reborn-casts')
            -- quick cast: the digit keys choose a skill slot (the slot hook), the mod then clicks at the cursor
            gear.config.quick_cast = true
            for key = 1, 5 do
                A.move(803 + 80 * key / 2, 465)
                step('slot key ' .. key, function() A.type(tostring(key)) end)
            end
            gear.config.quick_cast = false
            local ss = gear.hooks.stats('skillslot.select')
            print(('skillslot.select hook: %d calls, %d answered, %d busy'):format(ss.calls, ss.answered, ss.busy))
            -- melee swings (Shift + click) until the hero is hurt or the time is up
            local t = 0
            while t < gear.config.fight and hero:hp() and hero:hp() > 100 do
                A.key_down('shift')
                for k = 0, 7 do
                    local th = k * math.pi / 4
                    A.click(803 + 70 * math.cos(th), 465 + 42 * math.sin(th))
                    gear.wait(0.5)
                end
                A.key_up('shift')
                t = t + 4
            end
            print(('fight over: hero hp %s'):format(tostring(hero:hp())))
        end
        local total = 0
        for _, site in ipairs(gear.hooks.sites()) do
            if site.calls > 0 then print(('  site %s[%d] at %08x ran %d times'):format(site.hook, site.index, site.address, site.calls)); total = total + site.calls end
        end
        print(('site hook calls in play: %d'):format(total))
    end

    -- the level.factor hook: the engine's sites were hooked (the counters show whether the game asked meanwhile)
    local hs = gear.hooks.stats('level.factor')
    print(('level.factor hook: %d calls, %d answered, %d busy'):format(hs.calls, hs.answered, hs.busy))
    results.level_factor = hs
    local cs = gear.hooks.stats('combat.constant')
    print(('combat.constant hook: %d calls, %d answered, %d busy'):format(cs.calls, cs.answered, cs.busy))
    results.combat_constant = cs
    check('difficulty level of the running game', (gear.game.difficulty() or -1) >= 0 and gear.game.difficulty() <= 4, gear.game.difficulty())
    check('the level.factor hook answered the engine', hs.answered >= 7, ('%d calls, %d answered, %d busy'):format(hs.calls, hs.answered, hs.busy))

    -- which of the overlay's files the game really opened through it (informational; some are only read in some places)
    local rules = gear.read('overlay.txt') or ''
    local served_files, total = {}, 0
    for line in rules:gmatch('([^' .. string.char(13, 10) .. ']+)') do
        local game = line:match('^%s*([^#=]-)%s*=%s*%S')
        if game and game:lower() ~= 'saves' then
            local n = gear.files.served(game)
            if n > 0 then served_files[game] = n; total = total + 1 end
        end
    end
    results.overlay_served = served_files
    print(('overlay: %d files served to the game'):format(total))
    for game, n in pairs(served_files) do print(('  served %s x%d'):format(game, n)) end

    results.state = A.state()
    A.write('reborn.json', gear.json.encode(results))
    print(('%d passed, %d failed'):format(results.passed, results.failed))
    if gear.config.quit then A.quit(results.failed == 0 and 0 or 1) end
end)
